return {api_version=1,id="EX1_537",name="Explosive Shot",text="Deal $5 damage to a minion and $2 damage to adjacent ones.",set="EXPERT1",type="spell",class="hunter",rarity="rare",spell_school="fire",cost=5,target_mode="required",targets=function(ctx)return ctx:minions()end,on_play=function(ctx,self,target)local hits={{target,5}};for _,e in ipairs(ctx:adjacent_minions(target))do hits[#hits+1]={e,2}end;cardlib.effects.damage_batch(ctx, hits)end}
